function normalize(raw,{allowNew=true}={}){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('记录格式无效');if(!GAMES.some(g=>g[0]===raw.game))throw Error('记录包含不支持的游戏分类');if(!validDate(raw.eventDate||''))throw Error('赛事日期无效');if(raw.rounds!==undefined&&!Array.isArray(raw.rounds))throw Error('逐轮记录必须是列表');if((raw.rounds||[]).length>100)throw Error('单场最多支持 100 轮');const id=validUUID(raw.id)?raw.id:allowNew&&!raw.id?uuid():null;if(!id)throw Error('记录编号无效');if(raw.cover&&!coverRecord(raw.cover))throw Error('封面格式无效，仅接受本地内置图片或不超过 512 KB 的 PNG/JPG/WebP');const rounds=(raw.rounds||[]).map((r,i)=>{const result=r.result==='unplayed'?'':r.result||'';if(!['','W','L','D'].includes(result))throw Error('对局结果必须为 W、L、D 或待记录');return{id:validUUID(r.id)?r.id:allowNew&&!r.id?uuid():(()=>{throw Error('轮次编号无效');})(),label:checkedText(r.label||'R'+(i+1),80,'轮次名称'),result,opponentDeck:checkedText(r.opponentDeck,200,'对手牌型'),turnOrder:['first','second'].includes(r.turnOrder)?r.turnOrder:'',notes:checkedText(r.notes,2000,'本轮笔记'),iconIds:iconIds(r.iconIds),...normalizeBey(r,raw.game,0,allowNew)};});validateBeyEvent(rounds);if(new Set(rounds.map(r=>r.id)).size!==rounds.length)throw Error('轮次编号不能重复');return{id,revision:0,game:raw.game,eventName:checkedText(raw.eventName,200,'赛事标题'),eventDate:raw.eventDate||'',venue:checkedText(raw.venue,200,'地点'),deckName:checkedText(raw.deckName,200,'我的卡组或配置'),placement:checkedText(raw.placement,100,'最终名次'),notes:checkedText(raw.notes,12000,'赛事笔记'),iconIds:iconIds(raw.iconIds),cover:coverRecord(raw.cover),rounds,createdAt:checkedText(raw.createdAt,40,'创建时间'),updatedAt:checkedText(raw.updatedAt,40,'更新时间'),pendingSync:false};}
function totals(record){const t={wins:0,losses:0,draws:0,unreported:0,played:0};for(const r of record.rounds||[]){if(r.result==='W')t.wins++;else if(r.result==='L')t.losses++;else if(r.result==='D')t.draws++;else t.unreported++;}t.played=t.wins+t.losses+t.draws;return t;}

const TOP_CUT_STAGES=['Top 128','Top 64','Top 32','Top 16','Top 8','Top 4','Final'];
function roundCutKey(label,exact=false){
 const value=String(label||'').normalize('NFKC').trim().replace(/\s+/g,' ').toLowerCase();
 const top=value.match(exact?/^(?:top\s*|round\s+of\s+)(\d+)$/:/^(?:top\s*|round\s+of\s+)(\d+)/);
 if(top){const count=Number(top[1]);return Number.isSafeInteger(count)&&count>=2?(count===2?'Final':'Top '+count):'';}
 const chinese=value.match(exact?/^(\d+)\s*[强強](?:[赛賽])?$/:/^(\d+)\s*[强強]/);if(chinese){const count=Number(chinese[1]);return count>=2?(count===2?'Final':'Top '+count):'';}
 const rules=[['Top 4',exact?/^(?:semi[ -]?finals?|半[决決][赛賽]|[准準][决決][赛賽]|四[强強](?:[赛賽])?)$/:/^(?:semi[ -]?finals?\b|半[决決][赛賽]|[准準][决決][赛賽]|四[强強])/],['Top 8',exact?/^(?:quarter[ -]?finals?|八[强強](?:[赛賽])?)$/:/^(?:quarter[ -]?finals?\b|八[强強])/],['Top 16',exact?/^十六[强強](?:[赛賽])?$/:/^十六[强強]/],['Final',exact?/^(?:finals?|grand[ -]?finals?|(?:总|總)?[决決][赛賽])$/:/^(?:finals?\b|grand[ -]?finals?\b|(?:总|總)?[决決][赛賽])/],['Third place',exact?/^(?:3rd[ -]?place|third[ -]?place|季[军軍](?:[赛賽])?)$/:/^(?:3rd[ -]?place\b|third[ -]?place\b|季[军軍])/]];
 return rules.find(([,pattern])=>pattern.test(value))?.[0]||'';
}
function roundStage(round){return roundCutKey(round?.label)?'cut':'regular';}
function cutRank(label){const key=roundCutKey(label);return key==='Final'?2:key==='Third place'?3:key?Number(key.slice(4)):null;}
function stageLabel(kind){return kind==='cut'?'Top Cut / 淘汰赛':'常规轮次 / 预赛';}
function hasCutRounds(record){return(record.rounds||[]).some(round=>roundStage(round)==='cut');}
function stageEntries(record){if(!hasCutRounds(record))return[];return['regular','cut'].map(kind=>{const rounds=(record.rounds||[]).filter(round=>roundStage(round)===kind),part={...record,rounds};return{kind,rounds,totals:totals(part),bey:record.game==='beyblade'?Bey.summarize(part):null};}).filter(entry=>entry.rounds.length);}
function stageDescription(record,entry){const t=entry.totals;if(record.game==='beyblade')return'已记得分 '+Bey.formatPoints(entry.bey.total)+' / 已记失分 '+Bey.formatPoints(entry.bey.total,'against')+' · '+beyCoverage(entry.bey);return t.wins+' W · '+t.losses+' L · '+t.draws+' D'+(t.unreported?' · '+t.unreported+' 轮待记录':'');}
function appendStageOverview(host,record){const entries=stageEntries(record);if(!entries.length)return;const area=node('section',undefined,'report-stage-overview');area.setAttribute('aria-label','分阶段战绩');for(const entry of entries){const card=node('div',undefined,'report-stage-summary is-'+entry.kind);card.dataset.stage=entry.kind;card.dataset.stageKind=entry.kind==='cut'?'topcut':'regular';card.append(node('small',stageLabel(entry.kind)),node('strong',stageDescription(record,entry)),node('span',entry.rounds.length+' 轮 · '+entry.totals.played+' 轮结果已记'));area.append(card);}host.append(area);}
function stageDivider(kind,tag='div'){const heading=node(tag,undefined,'report-phase-divider is-'+kind);heading.dataset.reportStage=kind;heading.dataset.stageKind=kind==='cut'?'topcut':'regular';heading.append(node('strong',stageLabel(kind)));return heading;}
function stageStarts(record,index){return hasCutRounds(record)&&(index===0||roundStage(record.rounds[index-1])!==roundStage(record.rounds[index]));}
function addTopCutRounds(){if(!state.active)return;state.active=readForm();const start=$('topCutStart').value,index=TOP_CUT_STAGES.indexOf(start);if(index<0)return;const existing=new Set(state.active.rounds.map(round=>roundCutKey(round.label,true)).filter(Boolean)),missing=TOP_CUT_STAGES.slice(index).filter(label=>!existing.has(label));if(!missing.length){toast('所选 Top Cut 轮次已经添加。');return;}addRounds(missing);}
function pngStageRows(record,ctx){ctx.font='650 23px system-ui';return stageEntries(record).map(entry=>{const text=stageLabel(entry.kind)+' · '+stageDescription(record,entry),wrapped=lines(ctx,text,936);return{kind:entry.kind,lines:wrapped,height:wrapped.length*32+14};});}
