let storageFailure=null,draftFailure=null,lastReadRaw=null;
function readLocal(){let raw=null;try{raw=localStorage.getItem(STORE);const data=raw===null?[]:JSON.parse(raw);if(!Array.isArray(data))throw Error('记录库必须是列表');const records=data.map(r=>normalize(r,{allowNew:false}));if(new Set(records.map(r=>r.id)).size!==records.length)throw Error('记录编号重复');lastReadRaw=raw;storageFailure=null;return records;}catch(error){storageFailure={raw,message:'本机记录暂时无法安全读取，保存、删除和导入已暂停，原资料不会被覆盖。'+(raw===null?' 请检查此浏览器的网站储存权限。':' 请先下载原始资料备份。')};notice(localNotice);throw Error(storageFailure.message);}}
function writeLocal(records){localStorage.setItem(STORE,JSON.stringify(records));}
async function mutateLocal(transform){const action=()=>{const records=readLocal(),snapshot=lastReadRaw,next=transform(records);if(localStorage.getItem(STORE)!==snapshot)throw Error('其他标签页刚更新了本机记录，请重试；本次尚未写入。');writeLocal(next);state.records=next;return next;};return navigator.locks?.request?navigator.locks.request(STORE+'-write',action):action();}
function recordVersion(record){return record?JSON.stringify(normalize(record,{allowNew:false})):null;}
function checkLocalVersion(records,id){const current=records.find(r=>r.id===id)||null;if(state.baseRecord===undefined||recordVersion(current)!==state.baseRecord){const error=Error(current?'此记录已在其他标签页更新，未覆盖新版本。':'原记录已在其他标签页删除或版本未知，未重新创建。');error.localConflict=true;error.record=current;throw error;}}
function showLocalConflict(error){if(!error.localConflict)return false;state.conflict=error.record?clone(error.record):null;if(state.conflict){const dialog=$('conflictDialog');dialog.querySelector('.eyebrow').textContent='LOCAL RECORD UPDATED';dialog.querySelector('h2').textContent='这条本机记录有更新。';dialog.querySelector('h2+p').textContent='另一标签页已更新这条记录。你的编辑仍保留在本机草稿，尚未覆盖新版。可继续编辑草稿，或载入当前浏览器保存的最新版本后比较。';dialog.showModal();}else toast(error.message+' 编辑仍在草稿中，可先下载战报。');return true;}
function refreshStoredRecords({announce=false}={}){try{const records=readLocal();state.records=records;if(state.active&&!state.dirty){const current=records.find(r=>r.id===state.active.id);if(current){state.active=clone(current);state.baseRecord=recordVersion(current);renderEditor();if(state.view==='report')renderReport();}else{state.active=null;state.baseRecord=null;showView('report');}}renderList();if(!state.active&&records.length)selectRecord(ordered(records)[0],{force:true});notice(localNotice);if(announce)toast('已重新读取本机记录，未改动当前草稿。');}catch{renderList();}updateSync();}
function readDrafts({strict=false}={}){let raw=null;try{raw=localStorage.getItem(DRAFTS);const data=raw===null?{}:JSON.parse(raw);if(!data||typeof data!=='object'||Array.isArray(data))throw Error('草稿库必须是对象');if(Object.values(data).some(d=>!d||typeof d!=='object'||Array.isArray(d)||!d.record||typeof d.record!=='object'||Array.isArray(d.record)))throw Error('草稿条目格式无效');draftFailure=null;return data;}catch{draftFailure={raw,message:'本机草稿暂时无法读取，原草稿没有被覆盖。正式记录仍可保存；当前编辑也可先下载战报备份。'};notice(localNotice);if(strict)throw Error(draftFailure.message);return{};}}
function persistDraft(){if(!state.active)return;try{const drafts=readDrafts({strict:true});drafts[state.active.id]={savedAt:new Date().toISOString(),record:state.active,baseRecord:state.baseRecord};localStorage.setItem(DRAFTS,JSON.stringify(drafts));draftWarning=false;}catch{if(!draftWarning){notice('此浏览器无法保留更多草稿。请使用下载战报 / 打印保留本次编辑内容，或下载已有本机记录的 JSON 备份。');draftWarning=true;}}updateDraftButton();}
function dropDraft(id){try{const drafts=readDrafts({strict:true});delete drafts[id];localStorage.setItem(DRAFTS,JSON.stringify(drafts));}catch{}updateDraftButton();}
function updateDraftButton(){const count=Object.keys(readDrafts()).length;$('recoverDraft').hidden=!count;$('recoverDraft').textContent='恢复最近未保存的草稿'+(count>1?'（'+count+' 条）':'');}
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3600);}
function notice(text){localNotice=text;const host=$('notice');host.replaceChildren();host.hidden=!text&&!storageFailure&&!draftFailure;if(!storageFailure&&!draftFailure){host.textContent=text;return;}for(const [failure,id,label,name]of[[storageFailure,'exportRawLocal','下载原始本机资料','META-LAB-原始本机资料-待修复.json'],[draftFailure,'exportRawDrafts','下载原始草稿资料','META-LAB-原始草稿资料-待修复.json']]){if(!failure)continue;host.append(node('p',failure.message));if(failure.raw!==null){const raw=failure.raw,backup=node('button',label,'button quiet');backup.type='button';backup.id=id;backup.addEventListener('click',()=>download(new Blob([raw],{type:'application/json'}),name));host.append(backup);}}const retry=node('button','重新检查储存','button quiet');retry.type='button';retry.id='retryLocalStore';retry.addEventListener('click',()=>{readDrafts();refreshStoredRecords({announce:true});});host.append(retry);}
function updateSync(){for(const control of $('recordForm').querySelectorAll('input,select,textarea,button'))control.disabled=state.saving;$('newRecord').disabled=state.saving;$('emptyNewRecord').disabled=state.saving;$('importBackup').disabled=state.saving;$('recoverDraft').disabled=state.saving;$('syncState').textContent=state.saving?'正在保存到本机…':'仅保存在此浏览器 · 不上传';$('signInLink').hidden=true;$('saveRecord').disabled=state.saving||Boolean(storageFailure);$('saveRecord').textContent='保存到本机';$('deleteRecord').disabled=state.saving||Boolean(storageFailure);$('importBackup').disabled=state.saving||Boolean(storageFailure);}
async function request(){throw Error('此工具仅在本机保存，不提供云端读写。');}
function ordered(records){return records.slice().sort((a,b)=>(b.eventDate||'').localeCompare(a.eventDate||'')||(b.updatedAt||'').localeCompare(a.updatedAt||''));}
function filtered(){return ordered(state.records.filter(r=>(state.filter==='all'||r.game===state.filter)&&(!state.query||[r.eventName,r.venue,r.deckName,r.notes,...(r.game==='beyblade'?r.rounds.flatMap(round=>(round.beyblade?.bouts||[]).map(Bey.configLabel)):[])].join(' ').toLowerCase().includes(state.query))));}
function renderFilters(){const host=$('gameFilters');host.replaceChildren();for(const [id,label]of [['all','全部',null],...GAMES]){const b=node('button',label);b.type='button';b.disabled=state.mode==='loading'||state.paging;b.setAttribute('aria-pressed',String(state.filter===id));b.addEventListener('click',()=>{state.filter=id;renderFilters();if(state.mode==='api')loadPage(true);else renderList();});host.append(b);}}
function renderList(){const records=filtered(),host=$('recordList');host.replaceChildren();if(storageFailure){$('recordCount').textContent='资料待检查';host.append(node('p','本机资料未能安全读取，尚未判断赛事数量。请先下载原始资料备份。','list-empty'));for(const id of['summaryEvents','summaryPlayed','summaryRate','summaryWLD'])$(id).textContent='—';$('exportBackup').disabled=true;$('loadMoreRecords').hidden=true;$('paginationNote').textContent='原资料未被覆盖；重新检查储存后才恢复数量与统计。';return;}$('recordCount').textContent=records.length+' 场';if(!records.length)host.append(node('p',state.records.length?'没有匹配的赛事，试试其他分类或关键词。':'还没有记录。新增你的第一场赛事。','list-empty'));for(const r of records){const t=totals(r),b=node('button',undefined,'record-card');b.type='button';b.dataset.recordId=r.id;b.setAttribute('aria-current',String(state.active?.id===r.id));const meta=node('span',undefined,'record-card-meta');meta.append(node('b',gameName(r.game)),node('span',r.eventDate||'日期待补充'));b.append(meta,node('strong',r.eventName||'未命名赛事'),node('span',r.game==='beyblade'?(Bey.summarize(r).configurations.map(c=>c.label).join(' / ')||r.deckName||'配置待补充'):r.deckName||'卡组待补充','record-card-deck'));const footer=node('span',undefined,'record-card-footer');footer.append(node('span',r.game==='beyblade'?'已记得分 '+Bey.formatPoints(Bey.summarize(r).total)+' / 失分 '+Bey.formatPoints(Bey.summarize(r).total,'against'):`${t.wins} W · ${t.losses} L · ${t.draws} D`,'record-card-score'),node('span',r.pendingSync?'待同步':r.placement||(state.mode==='api'&&!state.cloudIds.has(r.id)?'仅本机':'尚无名次'),'record-card-placement'));b.append(footer);b.addEventListener('click',()=>selectRecord(r));host.append(b);}const aggregate=records.map(totals).reduce((a,t)=>({wins:a.wins+t.wins,losses:a.losses+t.losses,draws:a.draws+t.draws,played:a.played+t.played}),{wins:0,losses:0,draws:0,played:0});$('summaryEvents').textContent=records.length;$('summaryPlayed').textContent=aggregate.played;$('summaryRate').textContent=aggregate.played?Math.round(aggregate.wins/aggregate.played*100)+'%':'—';$('summaryWLD').replaceChildren(node('span',aggregate.wins),node('i','/'),node('span',aggregate.losses),node('i','/'),node('span',aggregate.draws));renderBeySeason(records);$('exportBackup').disabled=!state.records.length&&state.mode!=='api';$('loadMoreRecords').hidden=state.mode!=='api'||!state.nextCursor;$('loadMoreRecords').disabled=state.paging;$('loadMoreRecords').textContent=state.paging?'正在加载…':'加载更多赛事';$('paginationNote').textContent=state.mode==='api'?(state.nextCursor?'统计与搜索基于已载入记录；可继续加载更多。':'当前分类已全部载入；搜索与统计基于当前列表。'):'本机记录已全部载入；不会上传或计入公开统计。';}
function fresh(){return{id:uuid(),revision:0,game:state.filter==='all'?'ptcg':state.filter,eventName:'',eventDate:today(),venue:'',deckName:'',iconIds:[],cover:null,placement:'',notes:'',rounds:[{id:uuid(),label:'R1',result:'',opponentDeck:'',turnOrder:'',notes:'',iconIds:[],...(state.filter==='beyblade'?{beyblade:{bouts:[]}}:{})}],createdAt:'',updatedAt:''};}
function leaveActive(){if(state.dirty)persistDraft();return true;}
function newRecord(){if(state.saving){toast('正在保存，请稍候');return;}leaveActive();state.active=fresh();state.baseRecord=null;state.dirty=true;state.view='edit';renderEditor();renderList();showView('edit');$('eventName').focus();}
function selectRecord(record,{force=false}={}){if(state.saving&&!force){toast('正在保存，请稍候');return;}leaveActive();state.active=clone(record);state.baseRecord=recordVersion(record);state.dirty=false;renderEditor();renderList();showView('report');if(matchMedia('(max-width:760px)').matches)$('workspace').querySelector('.detail-workspace').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}
