function updateDeckLabel(){const bey=$('eventGame').value==='beyblade';$('deckNameLabel').textContent=bey?'赛事配置备注 / 3ON3 套组（选填）':'我的卡组';$('deckName').placeholder=bey?'可选：套组备注；逐轮填写完整配置与得分':'卡组名称、领袖或核心牌型';$('deckName').required=!bey;$('roundEditors').classList.toggle('bey-mode',bey);$('roundHelp').textContent=bey?'每轮可记录多套完整配置与得分；胜负和手动选择，不按分数推断。':'未结束的轮次保留“待记录”，不会计入胜负和。';}
function renderCoverOptions(){const select=$('coverSelect');select.replaceChildren(new Option('不使用封面',''));for(const cover of COVERS)select.add(new Option(cover.label,cover.src));if(state.active?.cover&&!COVERS.some(c=>c.src===state.active.cover.src))select.add(new Option(state.active.cover.label||'我的图片','custom'));select.value=state.active?.cover?(COVERS.find(c=>c.src===state.active.cover.src)?.src||'custom'):'';$('clearCover').hidden=!state.active?.cover;}
function optionSelect(options,value){const s=node('select');for(const [val,label]of options)s.add(new Option(label,val));s.value=value;return s;}
function roundField(label,control,field,className=''){const wrapper=node('label',undefined,className);wrapper.append(node('span',label),control);control.dataset.roundField=field;return wrapper;}
