function renderRecordIcons(){if(!state.active)return;renderIconEditor($('myDeckIcons'),state.active.iconIds,state.active.game);}
function refreshRoundIconEditors(){if(!state.active)return;for(const row of $('roundEditors').querySelectorAll('[data-round-id]')){const field=row.querySelector('.round-icon-editor');if(field)renderIconEditor(field,JSON.parse(row.dataset.iconIds||'[]'),state.active.game,row.dataset.roundId);}}
function setActiveIcons(roundId,ids){if(!state.active||state.saving)return;state.active=readForm();const next=iconIds(ids);if(roundId){const round=state.active.rounds.find(r=>r.id===roundId);if(!round)return;round.iconIds=next;const row=[...$('roundEditors').querySelectorAll('[data-round-id]')].find(n=>n.dataset.roundId===roundId);if(row){row.dataset.iconIds=JSON.stringify(next);renderIconEditor(row.querySelector('.round-icon-editor'),next,state.active.game,roundId);}}else{state.active.iconIds=next;renderRecordIcons();}markDirty();}
function openIconPicker(roundId=null){if(!state.active||state.saving)return;state.active=readForm();const round=roundId?state.active.rounds.find(r=>r.id===roundId):null;if(roundId&&!round)return;iconState.picker={recordId:state.active.id,game:state.active.game,roundId,selection:iconIds(round?round.iconIds:state.active.iconIds),name:round?round.opponentDeck:state.active.deckName};iconState.query='';iconState.page=1;$('iconPickerSearch').value='';$('iconPickerTitle').textContent=(round?'对手':state.active.game==='beyblade'?'我的配置':'我的卡组')+'代表图案';$('iconPickerGame').textContent=gameName(state.active.game)+' · 最多2张';renderIconPicker();$('iconPicker').showModal();$('iconPickerSearch').focus();}
function renderIconPicker(){const picker=iconState.picker;if(!picker)return;const selected=$('iconPickerSelected');selected.replaceChildren();for(const id of picker.selection){const chip=node('button',undefined,'icon-selected-chip');chip.type='button';chip.append(iconVisual([id],picker.game),node('span',iconLabel(id)),node('span','×','icon-remove-mark'));chip.setAttribute('aria-label','移除 '+iconLabel(id));chip.addEventListener('click',()=>{picker.selection=picker.selection.filter(x=>x!==id);renderIconPicker();});selected.append(chip);}if(!picker.selection.length)selected.append(node('span','尚未选择图案。原有卡组名称会保留。','icon-selection-empty'));
 const groups=String(iconState.query).split(/[\/／+＋、&＆]/).map(part=>iconSearchText(part).split(' ').filter(Boolean)).filter(words=>words.length),rows=iconState.icons.filter(x=>x.game===picker.game&&(!groups.length||groups.some(words=>words.every(w=>x.hay.includes(w))))),grid=$('iconPickerGrid');grid.replaceChildren();$('iconPickerRetry').hidden=iconState.status!=='error';$('iconPickerSuggest').disabled=!picker.name||iconState.status!=='ready';$('iconPickerMore').hidden=iconState.status!=='ready'||rows.length<=iconState.page*24;$('iconPickerStatus').textContent=iconState.status==='loading'?'正在读取图案目录…':iconState.status==='error'?'图案目录暂时无法读取，已选图案和战绩仍保留。':rows.length+' 个已收录图案 · 已选 '+picker.selection.length+' / 2';if(iconState.status!=='ready'){grid.append(node('p','可以关闭窗口继续填写战绩；目录可稍后重试。','icon-picker-empty'));return;}for(const data of rows.slice(0,iconState.page*24)){const option=node('button',undefined,'icon-option');option.type='button';option.dataset.iconOption=data.id;option.setAttribute('aria-pressed',String(picker.selection.includes(data.id)));option.append(iconVisual([data.id],picker.game),node('span',data.label));if(data.credit)option.append(node('small',data.credit,'icon-credit'));option.addEventListener('click',()=>{if(picker.selection.includes(data.id))picker.selection=picker.selection.filter(id=>id!==data.id);else if(picker.selection.length<2)picker.selection.push(data.id);else{toast('最多选择2张，请先移除一张。');return;}renderIconPicker();});grid.append(option);}if(!rows.length)grid.append(node('p','没有匹配图案。可试试已收录的中文、英文、日文名称，或清空搜索。','icon-picker-empty'));}
async function loadIconCatalog(){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);iconState.status='loading';if($('iconPicker').open)renderIconPicker();try{const r=await fetch(ICON_CATALOG_URL,{credentials:'same-origin',cache:'no-cache',signal:controller.signal});if(!r.ok)throw Error('catalog unavailable');const data=await r.json();if(data.version!==1||!Array.isArray(data.icons))throw Error('catalog format');const seen=new Set(),rows=[];for(const x of data.icons){if(!x||typeof x.id!=='string'||!/^[-a-z0-9_]{1,80}$/.test(x.id)||seen.has(x.id)||!GAMES.some(g=>g[0]===x.game)||typeof x.label!=='string'||x.label.length>160||!(typeof x.image==='string'&&/^\/[-a-zA-Z0-9_/.]+\.(png|webp|jpe?g|gif)$/.test(x.image)&&!x.image.includes('..')&&!x.image.startsWith('//')))throw Error('catalog entry');seen.add(x.id);rows.push({id:x.id,game:x.game,label:x.label,image:x.image,credit:typeof x.credit==='string'?x.credit.slice(0,160):'',...iconSpriteMeta(x),kind:['sprite','card','part'].includes(x.kind)?x.kind:'card',hay:iconSearchText([x.label,...(Array.isArray(x.aliases)?x.aliases.filter(v=>typeof v==='string'):[])].join(' '))});}iconState.icons=rows;iconState.byId=new Map(rows.map(x=>[x.id,x]));iconState.status='ready';}catch{iconState.status='error';}finally{clearTimeout(timer);}if(state.active){renderRecordIcons();refreshRoundIconEditors();if(state.view==='report')renderReport();}if($('iconPicker').open)renderIconPicker();}
